INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-01-001', 'MS-01', 'golden', 'Case-insensitive default collation matches every case variant of a literal', PARSE_JSON('{"description":"Case-insensitive default collation matches every case variant of a literal","dialect":"sqlserver","expected_rows":[[3]],"fix_pattern":"FX-MS-01-B","fixed":{"snowflake":"SELECT COUNT(*) FROM customer WHERE UPPER(status) = UPPER(''active'');"},"fixture":"CREATE TABLE customer (customer_id INTEGER, status VARCHAR);\\nINSERT INTO customer VALUES (1, ''Active''), (2, ''ACTIVE''), (3, ''active''), (4, ''Closed'');\\n","id":"TC-MS-01-001","issue_id":"MS-01","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT COUNT(*) FROM customer WHERE status = ''active'';"},"source_emulation":"-- SQL_Latin1_General_CP1_CI_AS: comparisons ignore case\\nSELECT COUNT(*) FROM customer WHERE lower(status) = lower(''active'');\\n","source_sql":"CREATE TABLE dbo.customer (customer_id INT, status VARCHAR(20));\\nSELECT COUNT(*) FROM dbo.customer WHERE status = ''active'';\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-01-002', 'MS-01', 'golden', 'COUNT(DISTINCT) collapses case variants under a case-insensitive collation', PARSE_JSON('{"description":"COUNT(DISTINCT) collapses case variants under a case-insensitive collation","dialect":"sqlserver","expected_rows":[[2]],"fix_pattern":"FX-MS-01-B","fixed":{"snowflake":"SELECT COUNT(DISTINCT UPPER(status)) FROM customer;"},"fixture":"CREATE TABLE customer (customer_id INTEGER, status VARCHAR);\\nINSERT INTO customer VALUES (1, ''Active''), (2, ''ACTIVE''), (3, ''active''), (4, ''Closed'');\\n","id":"TC-MS-01-002","issue_id":"MS-01","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT COUNT(DISTINCT status) FROM customer;"},"source_emulation":"SELECT COUNT(DISTINCT lower(status)) FROM customer;\\n","source_sql":"CREATE TABLE dbo.customer (customer_id INT, status VARCHAR(20));\\nSELECT COUNT(DISTINCT status) FROM dbo.customer;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-01-101', 'MS-01', 'detector', 'Numeric predicates are not collation-sensitive; an explicit CI collation is', PARSE_JSON('{"description":"Numeric predicates are not collation-sensitive; an explicit CI collation is","dialect":"sqlserver","expect_issues":["MS-01"],"expect_lines":{"MS-01":[2]},"id":"TC-MS-01-101","issue_id":"MS-01","kind":"detector","source_sql":"SELECT order_id FROM dbo.orders WHERE order_id = 42 AND amount > 10;\\nSELECT name COLLATE SQL_Latin1_General_CP1_CI_AS FROM dbo.customer;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-02-001', 'MS-02', 'golden', '''23:59:59.999'' rounds to next-day midnight in DATETIME, so SQL Server includes midnight rows', PARSE_JSON('{"description":"''23:59:59.999'' rounds to next-day midnight in DATETIME, so SQL Server includes midnight rows","dialect":"sqlserver","expected_rows":[[3]],"fix_pattern":"FX-MS-02-A","fixed":{"snowflake":"SELECT COUNT(*) FROM events\\nWHERE event_ts BETWEEN ''2026-10-01 00:00:00.000''::TIMESTAMP_NTZ(3) AND ''2026-10-02 00:00:00.000''::TIMESTAMP_NTZ(3);\\n"},"fixture":"CREATE TABLE events (event_id INTEGER, event_ts TIMESTAMP);\\nINSERT INTO events VALUES (1, ''2026-10-01 08:00:00''), (2, ''2026-10-01 23:59:59.997''), (3, ''2026-10-02 00:00:00'');\\n","id":"TC-MS-02-001","issue_id":"MS-02","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT COUNT(*) FROM events WHERE event_ts BETWEEN ''2026-10-01'' AND ''2026-10-01 23:59:59.999'';"},"source_emulation":"-- DATETIME stores 1/300 s ticks: the boundary literal is rounded to the nearest tick\\nSELECT COUNT(*) FROM events\\nWHERE event_ts BETWEEN TIMESTAMP ''2026-10-01 00:00:00''\\n  AND make_timestamp(CAST(round(epoch_ms(TIMESTAMP ''2026-10-01 23:59:59.999'') * 3 / 10.0) * 10 // 3 AS BIGINT) * 1000);\\n","source_sql":"CREATE TABLE dbo.events (event_id INT, event_ts DATETIME);\\nDECLARE @day_end DATETIME = ''2026-10-01 23:59:59.999'';\\nSELECT COUNT(*) FROM dbo.events WHERE event_ts BETWEEN ''2026-10-01'' AND @day_end;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-02-101', 'MS-02', 'profile', 'DATETIME source columns', PARSE_JSON('{"description":"DATETIME source columns","dialect":"sqlserver","expect_issues":["MS-02"],"id":"TC-MS-02-101","issue_id":"MS-02","kind":"profile","profile":{"columns":[{"column":"event_ts","source_type":"DATETIME","table":"dbo.events","target_type":"TIMESTAMP_NTZ(9)"}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-03-101', 'MS-03', 'detector', 'NOLOCK hints and isolation level', PARSE_JSON('{"description":"NOLOCK hints and isolation level","dialect":"sqlserver","expect_issues":["MS-03"],"id":"TC-MS-03-101","issue_id":"MS-03","kind":"detector","source_sql":"SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;\\nSELECT * FROM dbo.orders WITH (NOLOCK);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-04-001', 'MS-04', 'golden', 'SET DATEFORMAT dmy reads ''01/10/2026'' as 1 October; Snowflake AUTO reads 10 January', PARSE_JSON('{"description":"SET DATEFORMAT dmy reads ''01/10/2026'' as 1 October; Snowflake AUTO reads 10 January","dialect":"sqlserver","expected_rows":[[2]],"fix_pattern":"FX-MS-04-A","fixed":{"snowflake":"SELECT COUNT(*) FROM orders WHERE order_date = TO_DATE(''01/10/2026'', ''DD/MM/YYYY'');"},"fixture":"CREATE TABLE orders (order_id INTEGER, order_date DATE);\\nINSERT INTO orders VALUES (1, ''2026-10-01''), (2, ''2026-10-01''), (3, ''2026-01-10'');\\n","id":"TC-MS-04-001","issue_id":"MS-04","kind":"golden","naive":{"duckdb":"-- Snowflake DATE_INPUT_FORMAT=AUTO resolves MM/DD/YYYY\\nSELECT COUNT(*) FROM orders WHERE order_date = CAST(strptime(''01/10/2026'', ''%m/%d/%Y'') AS DATE);\\n","expect":"diverge","snowflake":"SELECT COUNT(*) FROM orders WHERE order_date = ''01/10/2026'';"},"source_emulation":"SELECT COUNT(*) FROM orders WHERE order_date = CAST(strptime(''01/10/2026'', ''%d/%m/%Y'') AS DATE);\\n","source_sql":"SET DATEFORMAT dmy;\\nSELECT COUNT(*) FROM dbo.orders WHERE order_date = ''01/10/2026'';\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-05-101', 'MS-05', 'detector', 'TRY/CATCH with @@ROWCOUNT and RAISERROR', PARSE_JSON('{"description":"TRY/CATCH with @@ROWCOUNT and RAISERROR","dialect":"sqlserver","expect_issues":["MS-05"],"id":"TC-MS-05-101","issue_id":"MS-05","kind":"detector","source_sql":"BEGIN TRY\\n  UPDATE dbo.orders SET status = ''X'' WHERE order_id = @id;\\n  IF @@ROWCOUNT = 0 RAISERROR(''not found'', 16, 1);\\nEND TRY\\nBEGIN CATCH\\n  THROW;\\nEND CATCH\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-06-101', 'MS-06', 'detector', 'Dynamic SQL', PARSE_JSON('{"description":"Dynamic SQL","dialect":"sqlserver","expect_issues":["MS-06"],"id":"TC-MS-06-101","issue_id":"MS-06","kind":"detector","source_sql":"DECLARE @sql NVARCHAR(MAX) = N''SELECT * FROM '' + @table;\\nEXEC sp_executesql @sql;\\nEXEC (@sql);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-07-101', 'MS-07', 'detector', 'SSIS package containing a C# script task', PARSE_JSON('{"description":"SSIS package containing a C# script task","dialect":"sqlserver","expect_issues":["MS-07"],"id":"TC-MS-07-101","issue_id":"MS-07","kind":"detector","source_sql":"<DTS:Executable DTS:ExecutableType=\\"Microsoft.ScriptTask\\" DTS:ObjectName=\\"Compute bonus\\">\\n  <DTS:ObjectData><ScriptProject Language=\\"CSharp\\"/></DTS:ObjectData>\\n</DTS:Executable>\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-08-001', 'MS-08', 'golden', 'ON DELETE CASCADE removes child rows in SQL Server; Snowflake leaves orphans', PARSE_JSON('{"description":"ON DELETE CASCADE removes child rows in SQL Server; Snowflake leaves orphans","dialect":"sqlserver","expected_rows":[[1]],"fix_pattern":"FX-MS-08-A","fixed":{"snowflake":"DELETE FROM orders WHERE customer_id IN (SELECT customer_id FROM customer WHERE customer_id = 1);\\nDELETE FROM customer WHERE customer_id = 1;\\nSELECT COUNT(*) FROM orders;\\n"},"fixture":"CREATE TABLE customer (customer_id INTEGER, name VARCHAR);\\nINSERT INTO customer VALUES (1, ''A''), (2, ''B'');\\nCREATE TABLE orders (order_id INTEGER, customer_id INTEGER);\\nINSERT INTO orders VALUES (10, 1), (11, 1), (12, 2);\\n","id":"TC-MS-08-001","issue_id":"MS-08","kind":"golden","naive":{"expect":"diverge","snowflake":"DELETE FROM customer WHERE customer_id = 1;\\nSELECT COUNT(*) FROM orders;\\n"},"source_emulation":"-- the engine cascades the parent delete to orders\\nSELECT COUNT(*) FROM orders o WHERE NOT EXISTS (SELECT 1 FROM customer c WHERE c.customer_id = o.customer_id AND c.customer_id = 1);\\n","source_sql":"CREATE TABLE dbo.customer (customer_id INT PRIMARY KEY, name VARCHAR(50));\\nCREATE TABLE dbo.orders (\\n  order_id INT PRIMARY KEY,\\n  customer_id INT REFERENCES dbo.customer (customer_id) ON DELETE CASCADE\\n);\\nDELETE FROM dbo.customer WHERE customer_id = 1;\\nSELECT COUNT(*) FROM dbo.orders;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-08-101', 'MS-08', 'profile', 'Enforced cascades and triggers in the catalog', PARSE_JSON('{"description":"Enforced cascades and triggers in the catalog","dialect":"sqlserver","expect_issues":["MS-08"],"id":"TC-MS-08-101","issue_id":"MS-08","kind":"profile","profile":{"constraints":[{"kind":"foreign_key","on_delete":"cascade","table":"dbo.orders"}],"triggers":[{"name":"trg_orders_audit","table":"dbo.orders"}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-09-101', 'MS-09', 'detector', 'Cursor loop with singleton updates', PARSE_JSON('{"description":"Cursor loop with singleton updates","dialect":"sqlserver","expect_issues":["MS-09"],"id":"TC-MS-09-101","issue_id":"MS-09","kind":"detector","source_sql":"DECLARE c CURSOR FOR SELECT order_id FROM dbo.orders;\\nOPEN c;\\nFETCH NEXT FROM c INTO @id;\\nWHILE @@FETCH_STATUS = 0\\nBEGIN\\n  UPDATE dbo.orders SET status = ''X'' WHERE order_id = @id;\\n  FETCH NEXT FROM c INTO @id;\\nEND\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-MS-10-101', 'MS-10', 'detector', 'Synapse distribution and columnstore', PARSE_JSON('{"description":"Synapse distribution and columnstore","dialect":"sqlserver","expect_issues":["MS-10"],"id":"TC-MS-10-101","issue_id":"MS-10","kind":"detector","source_sql":"CREATE TABLE dbo.fact_sales (id INT, amount DECIMAL(12,2))\\nWITH (DISTRIBUTION = HASH(id), CLUSTERED COLUMNSTORE INDEX);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-01-101', 'NZ-01', 'detector', 'Distribution and organisation clauses', PARSE_JSON('{"description":"Distribution and organisation clauses","dialect":"netezza","expect_issues":["NZ-01"],"id":"TC-NZ-01-101","issue_id":"NZ-01","kind":"detector","source_sql":"CREATE TABLE sales.fact (id INTEGER, d DATE) DISTRIBUTE ON (id) ORGANIZE ON (d);\\nGROOM TABLE sales.fact;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-02-101', 'NZ-02', 'detector', 'NZPLSQL procedure', PARSE_JSON('{"description":"NZPLSQL procedure","dialect":"netezza","expect_issues":["NZ-02"],"id":"TC-NZ-02-101","issue_id":"NZ-02","kind":"detector","source_sql":"CREATE OR REPLACE PROCEDURE etl.load_day(DATE) RETURNS INTEGER LANGUAGE NZPLSQL AS\\nBEGIN_PROC\\nBEGIN\\n  INSERT INTO sales.fact SELECT * FROM stage.fact;\\n  RETURN 0;\\nEND;\\nEND_PROC;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-03-101', 'NZ-03', 'detector', 'nzsql/nzload shell orchestration', PARSE_JSON('{"description":"nzsql/nzload shell orchestration","dialect":"netezza","expect_issues":["NZ-03"],"id":"TC-NZ-03-101","issue_id":"NZ-03","kind":"detector","source_sql":"#!/bin/sh\\nnzload -db SALES -t FACT -df /data/fact.dat -delim ''|'' || exit 1\\nnzsql -db SALES -f /etl/post_load.sql\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-04-001', 'NZ-04', 'golden', 'Integer division truncates in Netezza and returns a decimal in Snowflake', PARSE_JSON('{"description":"Integer division truncates in Netezza and returns a decimal in Snowflake","dialect":"netezza","expected_rows":[[3]],"fix_pattern":"FX-NZ-04-A","fixed":{"snowflake":"SELECT TRUNC(SUM(units) / COUNT(*)) AS avg_units FROM daily_units;"},"fixture":"CREATE TABLE daily_units (store_id INTEGER, units INTEGER);\\nINSERT INTO daily_units VALUES (1, 7), (2, 2), (3, 2);\\n","id":"TC-NZ-04-001","issue_id":"NZ-04","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT SUM(units) / COUNT(*) AS avg_units FROM daily_units;"},"source_emulation":"SELECT SUM(units) // COUNT(*) FROM daily_units;\\n","source_sql":"CREATE TABLE sales.daily_units (store_id INTEGER, units INTEGER) DISTRIBUTE ON (store_id);\\nSELECT SUM(units) / COUNT(*) AS avg_units FROM sales.daily_units;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-05-001', 'NZ-05', 'golden', 'EXTRACT(DOW) is 1-7 (Sunday = 1) in Netezza and 0-6 in Snowflake (WEEK_START = 0)', PARSE_JSON('{"description":"EXTRACT(DOW) is 1-7 (Sunday = 1) in Netezza and 0-6 in Snowflake (WEEK_START = 0)","dialect":"netezza","expected_rows":[[1,1],[2,2]],"fix_pattern":"FX-NZ-05-A","fixed":{"snowflake":"SELECT DAYOFWEEK(sale_date) + 1 AS dow, COUNT(*) FROM daily GROUP BY 1 ORDER BY 1;"},"fixture":"CREATE TABLE daily (sale_date DATE);\\nINSERT INTO daily VALUES (''2026-10-04''), (''2026-10-05''), (''2026-10-05'');\\n","id":"TC-NZ-05-001","issue_id":"NZ-05","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT EXTRACT(DOW FROM sale_date) AS dow, COUNT(*) FROM daily GROUP BY 1 ORDER BY 1;"},"source_emulation":"-- Netezza: Sunday = 1 ... Saturday = 7\\nSELECT dayofweek(sale_date) + 1 AS dow, COUNT(*) FROM daily GROUP BY 1 ORDER BY 1;\\n","source_sql":"SELECT EXTRACT(DOW FROM sale_date) AS dow, COUNT(*) FROM sales.daily GROUP BY 1 ORDER BY 1;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-NZ-06-101', 'NZ-06', 'profile', 'Appliance end of support inside the horizon', PARSE_JSON('{"description":"Appliance end of support inside the horizon","dialect":"netezza","expect_issues":["NZ-06"],"id":"TC-NZ-06-101","issue_id":"NZ-06","kind":"profile","profile":{"platform":{"as_of":"2026-10-01","end_of_support":"2027-06-30"}},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-01-001', 'OR-01', 'golden', 'IS NULL filter counts '''' as NULL in Oracle only', PARSE_JSON('{"description":"IS NULL filter counts '''' as NULL in Oracle only","dialect":"oracle","expected_rows":[[2]],"fix_pattern":"FX-OR-01-B","fixed":{"snowflake":"SELECT COUNT(*) FROM customer WHERE (middle_name IS NULL OR middle_name = '''');"},"fixture":"CREATE TABLE customer (customer_id INTEGER, first_name VARCHAR, middle_name VARCHAR);\\nINSERT INTO customer VALUES (1, ''Ann'', NULL), (2, ''Bob'', ''''), (3, ''Cy'', ''J'');\\n","id":"TC-OR-01-001","issue_id":"OR-01","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT COUNT(*) FROM customer WHERE middle_name IS NULL;"},"source_emulation":"-- Oracle stores the empty string as NULL\\nSELECT COUNT(*) FROM customer WHERE nullif(middle_name, '''') IS NULL;\\n","source_sql":"CREATE TABLE crm.customer (customer_id NUMBER(10), first_name VARCHAR2(40), middle_name VARCHAR2(40));\\nSELECT COUNT(*) FROM crm.customer WHERE middle_name IS NULL;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-01-002', 'OR-01', 'golden', 'Concatenation with NULL yields the other operand in Oracle and NULL in Snowflake', PARSE_JSON('{"description":"Concatenation with NULL yields the other operand in Oracle and NULL in Snowflake","dialect":"oracle","expected_rows":[[1,"Ann "],[2,"Bob "],[3,"Cy J"]],"fix_pattern":"FX-OR-01-B","fixed":{"snowflake":"SELECT customer_id, first_name || '' '' || COALESCE(middle_name, '''') AS display_name FROM customer ORDER BY customer_id;"},"fixture":"CREATE TABLE customer (customer_id INTEGER, first_name VARCHAR, middle_name VARCHAR);\\nINSERT INTO customer VALUES (1, ''Ann'', NULL), (2, ''Bob'', ''''), (3, ''Cy'', ''J'');\\n","id":"TC-OR-01-002","issue_id":"OR-01","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT customer_id, first_name || '' '' || middle_name AS display_name FROM customer ORDER BY customer_id;"},"source_emulation":"-- Oracle || treats NULL as the empty string\\nSELECT customer_id, first_name || '' '' || coalesce(middle_name, '''') FROM customer ORDER BY customer_id;\\n","source_sql":"CREATE TABLE crm.customer (customer_id NUMBER(10), first_name VARCHAR2(40), middle_name VARCHAR2(40));\\nSELECT customer_id, first_name || '' '' || middle_name AS display_name FROM crm.customer ORDER BY customer_id;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-01-101', 'OR-01', 'profile', 'Snowflake null count lower than source after load (empty strings landed as '''')', PARSE_JSON('{"description":"Snowflake null count lower than source after load (empty strings landed as '''')","dialect":"oracle","expect_issues":["OR-01"],"id":"TC-OR-01-101","issue_id":"OR-01","kind":"profile","profile":{"columns":[{"column":"middle_name","source_stats":{"null_count":120},"source_type":"VARCHAR2(40)","table":"crm.customer","target_stats":{"empty_string_count":40,"null_count":80},"target_type":"VARCHAR(40)"},{"column":"first_name","source_stats":{"null_count":0},"source_type":"VARCHAR2(40)","table":"crm.customer","target_stats":{"empty_string_count":0,"null_count":0},"target_type":"VARCHAR(40)"}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-02-001', 'OR-02', 'golden', 'Unscaled NUMBER becomes NUMBER(38,0) and rounds prices', PARSE_JSON('{"description":"Unscaled NUMBER becomes NUMBER(38,0) and rounds prices","dialect":"oracle","expected_rows":[[66.57]],"fix_pattern":"FX-OR-02-A","fixed":{"snowflake":"CREATE TABLE invoice_line (line_id NUMBER(10), unit_price NUMBER(38, 4), qty NUMBER(5));\\nINSERT INTO invoice_line SELECT line_id, unit_price, qty FROM invoice_line_stage;\\nSELECT SUM(unit_price * qty) FROM invoice_line;\\n"},"fixture":"CREATE TABLE invoice_line_stage (line_id INTEGER, unit_price DECIMAL(38,4), qty INTEGER);\\nINSERT INTO invoice_line_stage VALUES (1, 19.99, 3), (2, 0.25, 10), (3, 4.10, 1);\\n","id":"TC-OR-02-001","issue_id":"OR-02","kind":"golden","naive":{"expect":"diverge","snowflake":"CREATE TABLE invoice_line (line_id NUMBER(10), unit_price NUMBER, qty NUMBER(5));\\nINSERT INTO invoice_line SELECT line_id, unit_price, qty FROM invoice_line_stage;\\nSELECT SUM(unit_price * qty) FROM invoice_line;\\n"},"source_emulation":"-- Oracle NUMBER without scale stores the decimals\\nSELECT SUM(unit_price * qty) FROM invoice_line_stage;\\n","source_sql":"CREATE TABLE fin.invoice_line (line_id NUMBER(10), unit_price NUMBER, qty NUMBER(5));\\nSELECT SUM(unit_price * qty) FROM fin.invoice_line;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-02-101', 'OR-02', 'profile', 'Profiled max scale exceeds the target scale', PARSE_JSON('{"description":"Profiled max scale exceeds the target scale","dialect":"oracle","expect_issues":["OR-02"],"id":"TC-OR-02-101","issue_id":"OR-02","kind":"profile","profile":{"columns":[{"column":"unit_price","source_stats":{"max_scale":4},"source_type":"NUMBER","table":"fin.invoice_line","target_type":"NUMBER(38,0)"},{"column":"qty","source_stats":{"max_scale":0},"source_type":"NUMBER(5)","table":"fin.invoice_line","target_type":"NUMBER(5,0)"}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-03-001', 'OR-03', 'golden', 'Oracle DATE keeps the time of day; mapping to Snowflake DATE drops it', PARSE_JSON('{"description":"Oracle DATE keeps the time of day; mapping to Snowflake DATE drops it","dialect":"oracle","expected_rows":[[2]],"fix_pattern":"FX-OR-03-A","fixed":{"snowflake":"CREATE TABLE orders (order_id NUMBER(10), order_dt TIMESTAMP_NTZ);\\nINSERT INTO orders SELECT order_id, order_dt FROM orders_stage;\\nSELECT COUNT(*) FROM orders WHERE order_dt >= TO_TIMESTAMP(''2026-10-01 12:00'', ''YYYY-MM-DD HH24:MI'');\\n"},"fixture":"CREATE TABLE orders_stage (order_id INTEGER, order_dt TIMESTAMP);\\nINSERT INTO orders_stage VALUES (1, ''2026-10-01 09:15:00''), (2, ''2026-10-01 13:45:00''), (3, ''2026-10-02 08:00:00'');\\n","id":"TC-OR-03-001","issue_id":"OR-03","kind":"golden","naive":{"expect":"diverge","snowflake":"CREATE TABLE orders (order_id NUMBER(10), order_dt DATE);\\nINSERT INTO orders SELECT order_id, CAST(order_dt AS DATE) FROM orders_stage;\\nSELECT COUNT(*) FROM orders WHERE order_dt >= TO_TIMESTAMP(''2026-10-01 12:00'', ''YYYY-MM-DD HH24:MI'');\\n"},"source_emulation":"SELECT COUNT(*) FROM orders_stage WHERE order_dt >= TIMESTAMP ''2026-10-01 12:00:00'';\\n","source_sql":"CREATE TABLE sales.orders (order_id NUMBER(10), order_dt DATE);\\nSELECT COUNT(*) FROM sales.orders WHERE order_dt >= TO_DATE(''2026-10-01 12:00'', ''YYYY-MM-DD HH24:MI'');\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-03-101', 'OR-03', 'profile', 'DATE column with time-of-day values mapped to DATE', PARSE_JSON('{"description":"DATE column with time-of-day values mapped to DATE","dialect":"oracle","expect_issues":["OR-03"],"id":"TC-OR-03-101","issue_id":"OR-03","kind":"profile","profile":{"columns":[{"column":"order_dt","source_stats":{"has_time_component":true},"source_type":"DATE","table":"sales.orders","target_type":"DATE"}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-04-101', 'OR-04', 'detector', 'Package with state and an autonomous logging procedure', PARSE_JSON('{"description":"Package with state and an autonomous logging procedure","dialect":"oracle","expect_issues":["OR-04","XD-12"],"id":"TC-OR-04-101","issue_id":"OR-04","kind":"detector","source_sql":"CREATE OR REPLACE PACKAGE BODY etl_pkg AS\\n  g_batch_id NUMBER(10);\\n  PROCEDURE log_msg(p_msg VARCHAR2) IS\\n    PRAGMA AUTONOMOUS_TRANSACTION;\\n  BEGIN\\n    INSERT INTO etl_log VALUES (g_batch_id, p_msg);\\n    COMMIT;\\n  END;\\nEND etl_pkg;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-05-101', 'OR-05', 'detector', 'BULK COLLECT and FORALL loops', PARSE_JSON('{"description":"BULK COLLECT and FORALL loops","dialect":"oracle","expect_issues":["OR-05"],"id":"TC-OR-05-101","issue_id":"OR-05","kind":"detector","source_sql":"DECLARE\\n  TYPE t_ids IS TABLE OF NUMBER(10);\\n  l_ids t_ids;\\nBEGIN\\n  SELECT order_id BULK COLLECT INTO l_ids FROM sales.orders;\\n  FORALL i IN 1 .. l_ids.COUNT\\n    UPDATE sales.orders SET status = ''X'' WHERE order_id = l_ids(i);\\nEND;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-06-101', 'OR-06', 'detector', 'Legacy (+) outer join', PARSE_JSON('{"description":"Legacy (+) outer join","dialect":"oracle","expect_issues":["OR-06"],"id":"TC-OR-06-101","issue_id":"OR-06","kind":"detector","source_sql":"SELECT o.order_id, c.name FROM sales.orders o, crm.customer c\\nWHERE o.customer_id = c.customer_id (+);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-07-101', 'OR-07', 'detector', 'Audit trigger', PARSE_JSON('{"description":"Audit trigger","dialect":"oracle","expect_issues":["OR-07"],"id":"TC-OR-07-101","issue_id":"OR-07","kind":"detector","source_sql":"CREATE OR REPLACE TRIGGER trg_orders_audit\\nBEFORE UPDATE ON sales.orders FOR EACH ROW\\nBEGIN\\n  :NEW.updated_at := SYSDATE;\\nEND;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-08-001', 'OR-08', 'golden', 'TO_CHAR(date) without a format follows NLS_DATE_FORMAT in Oracle and DATE_OUTPUT_FORMAT in Snowflake', PARSE_JSON('{"description":"TO_CHAR(date) without a format follows NLS_DATE_FORMAT in Oracle and DATE_OUTPUT_FORMAT in Snowflake","dialect":"oracle","expected_rows":[[1,"01-OCT-26"],[2,"25-DEC-26"]],"fix_pattern":"FX-OR-08-A","fixed":{"duckdb":"-- Snowflake TO_CHAR(d, ''DD-MON-YY'') renders ''Oct''; UPPER restores the Oracle rendering\\nSELECT order_id, upper(strftime(order_dt, ''%d-%b-%y'')) AS order_day FROM orders ORDER BY order_id;\\n","snowflake":"SELECT order_id, UPPER(TO_CHAR(order_dt, ''DD-MON-YY'')) AS order_day FROM orders ORDER BY order_id;"},"fixture":"CREATE TABLE orders (order_id INTEGER, order_dt DATE);\\nINSERT INTO orders VALUES (1, ''2026-10-01''), (2, ''2026-12-25'');\\n","id":"TC-OR-08-001","issue_id":"OR-08","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT order_id, TO_CHAR(order_dt) AS order_day FROM orders ORDER BY order_id;"},"source_emulation":"-- NLS_DATE_FORMAT = DD-MON-RR renders upper-case month abbreviations\\nSELECT order_id, upper(strftime(order_dt, ''%d-%b-%y'')) FROM orders ORDER BY order_id;\\n","source_sql":"ALTER SESSION SET NLS_DATE_FORMAT = ''DD-MON-RR'';\\nSELECT order_id, TO_CHAR(order_dt) AS order_day FROM sales.orders ORDER BY order_id;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-OR-08-101', 'OR-08', 'detector', 'TO_CHAR with an explicit format model is not NLS-dependent', PARSE_JSON('{"description":"TO_CHAR with an explicit format model is not NLS-dependent","dialect":"oracle","expect_absent":["OR-08"],"expect_issues":[],"id":"TC-OR-08-101","issue_id":"OR-08","kind":"detector","source_sql":"SELECT TO_CHAR(order_dt, ''YYYY-MM-DD'') FROM sales.orders;\\n"}');
