INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-01-001', 'TD-01', 'golden', 'SET table silently drops re-delivered duplicate rows; naive Snowflake table keeps them', PARSE_JSON('{"description":"SET table silently drops re-delivered duplicate rows; naive Snowflake table keeps them","dialect":"teradata","expected_rows":[[3,175.5]],"fix_pattern":"FX-TD-01-A","fixed":{"snowflake":"CREATE TABLE orders (order_id INTEGER NOT NULL, customer_id INTEGER, amount NUMBER(12, 2));\\nINSERT INTO orders\\nSELECT order_id, customer_id, amount FROM orders_batch\\nQUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, customer_id, amount ORDER BY order_id) = 1;\\nSELECT COUNT(*), SUM(amount) FROM orders;\\n"},"fixture":"CREATE TABLE orders_batch (order_id INTEGER, customer_id INTEGER, amount DECIMAL(12,2));\\nINSERT INTO orders_batch VALUES (1, 10, 100.00), (2, 11, 50.00), (2, 11, 50.00), (3, 12, 25.50), (3, 12, 25.50);\\n","id":"TC-TD-01-001","issue_id":"TD-01","kind":"golden","naive":{"expect":"diverge","snowflake":"CREATE TABLE orders (order_id INTEGER NOT NULL, customer_id INTEGER, amount NUMBER(12, 2));\\nINSERT INTO orders SELECT order_id, customer_id, amount FROM orders_batch;\\nSELECT COUNT(*), SUM(amount) FROM orders;\\n"},"source_emulation":"-- Teradata SET table: exact duplicate rows are discarded on INSERT ... SELECT\\nCREATE TABLE orders (order_id INTEGER, customer_id INTEGER, amount DECIMAL(12,2));\\nINSERT INTO orders SELECT DISTINCT order_id, customer_id, amount FROM orders_batch;\\nSELECT COUNT(*), SUM(amount) FROM orders;\\n","source_sql":"CREATE SET TABLE sales.orders (\\n  order_id    INTEGER NOT NULL,\\n  customer_id INTEGER,\\n  amount      DECIMAL(12,2)\\n) PRIMARY INDEX (order_id);\\nINSERT INTO sales.orders SELECT order_id, customer_id, amount FROM stage.orders_batch;\\nSELECT COUNT(*), SUM(amount) FROM sales.orders;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-01-101', 'TD-01', 'detector', 'MULTISET tables and UPDATE ... SET are not SET tables', PARSE_JSON('{"description":"MULTISET tables and UPDATE ... SET are not SET tables","dialect":"teradata","expect_absent":["TD-01"],"expect_issues":[],"id":"TC-TD-01-101","issue_id":"TD-01","kind":"detector","source_sql":"CREATE MULTISET TABLE sales.orders_m (order_id INTEGER) PRIMARY INDEX (order_id);\\nUPDATE sales.orders_m SET order_id = order_id + 1 WHERE order_id = 0;\\n-- CREATE SET TABLE in a comment must not count\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-01-102', 'TD-01', 'profile', 'DBC.TablesV reports a SET table and the target holds more rows than distinct source rows', PARSE_JSON('{"description":"DBC.TablesV reports a SET table and the target holds more rows than distinct source rows","dialect":"teradata","expect_issues":["TD-01"],"id":"TC-TD-01-102","issue_id":"TD-01","kind":"profile","profile":{"tables":[{"kind":"SET","name":"sales.orders","source_row_count":3,"target_row_count":5},{"kind":"MULTISET","name":"sales.lines","source_row_count":9,"target_row_count":9}]},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-02-001', 'TD-02', 'golden', 'NOT CASESPECIFIC column filter matches all case variants in Teradata only', PARSE_JSON('{"description":"NOT CASESPECIFIC column filter matches all case variants in Teradata only","dialect":"teradata","expected_rows":[[3]],"fix_pattern":"FX-TD-02-B","fixed":{"snowflake":"SELECT COUNT(*) FROM customer WHERE UPPER(last_name) = UPPER(''SMITH'');"},"fixture":"CREATE TABLE customer (customer_id INTEGER, last_name VARCHAR);\\nINSERT INTO customer VALUES (1, ''Smith''), (2, ''SMITH''), (3, ''smith''), (4, ''Jones'');\\n","id":"TC-TD-02-001","issue_id":"TD-02","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT COUNT(*) FROM customer WHERE last_name = ''SMITH'';"},"source_emulation":"-- NOT CASESPECIFIC: comparison ignores case\\nSELECT COUNT(*) FROM customer WHERE lower(last_name) = lower(''SMITH'');\\n","source_sql":"CREATE MULTISET TABLE crm.customer (\\n  customer_id INTEGER,\\n  last_name   VARCHAR(50) NOT CASESPECIFIC\\n);\\nSELECT COUNT(*) FROM crm.customer WHERE last_name = ''SMITH'';\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-02-101', 'TD-02', 'detector', 'CASESPECIFIC columns in ANSI mode are not flagged; NOT CASESPECIFIC on another column is', PARSE_JSON('{"description":"CASESPECIFIC columns in ANSI mode are not flagged; NOT CASESPECIFIC on another column is","dialect":"teradata","expect_issues":["TD-02"],"expect_lines":{"TD-02":[3]},"id":"TC-TD-02-101","issue_id":"TD-02","kind":"detector","source_sql":"CREATE MULTISET TABLE crm.codes (code VARCHAR(10) CASESPECIFIC, label VARCHAR(40));\\nSELECT code FROM crm.codes WHERE code = ''Ab'';\\nCREATE MULTISET TABLE crm.people (name VARCHAR(40) NOT CASESPECIFIC);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-03-001', 'TD-03', 'golden', 'CHAR(5) codes exported with pad characters no longer join to VARCHAR codes', PARSE_JSON('{"description":"CHAR(5) codes exported with pad characters no longer join to VARCHAR codes","dialect":"teradata","expected_rows":[["North",15],["South",7.25]],"fix_pattern":"FX-TD-03-A","fixed":{"snowflake":"CREATE TABLE branch_clean AS SELECT CAST(RTRIM(branch_cd) AS VARCHAR(5)) AS branch_cd, branch_name FROM branch;\\nSELECT b.branch_name, SUM(t.amount) FROM txn t JOIN branch_clean b ON t.branch_cd = b.branch_cd\\nGROUP BY b.branch_name ORDER BY 1;\\n"},"fixture":"CREATE TABLE branch (branch_cd VARCHAR, branch_name VARCHAR);\\nINSERT INTO branch VALUES (''AB   '', ''North''), (''CDE  '', ''South'');\\nCREATE TABLE txn (txn_id INTEGER, branch_cd VARCHAR, amount DECIMAL(12,2));\\nINSERT INTO txn VALUES (1, ''AB'', 10.00), (2, ''AB'', 5.00), (3, ''CDE'', 7.25);\\n","id":"TC-TD-03-001","issue_id":"TD-03","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT b.branch_name, SUM(t.amount) FROM txn t JOIN branch b ON t.branch_cd = b.branch_cd\\nGROUP BY b.branch_name ORDER BY 1;\\n"},"source_emulation":"-- Teradata compares CHAR values with pad semantics (trailing spaces ignored)\\nSELECT b.branch_name, SUM(t.amount) FROM txn t JOIN branch b ON rtrim(t.branch_cd) = rtrim(b.branch_cd)\\nGROUP BY b.branch_name ORDER BY 1;\\n","source_sql":"CREATE MULTISET TABLE ref.branch (branch_cd CHAR(5) NOT NULL, branch_name VARCHAR(40));\\nCREATE MULTISET TABLE fin.txn (txn_id INTEGER, branch_cd VARCHAR(5), amount DECIMAL(12,2));\\nSELECT b.branch_name, SUM(t.amount)\\nFROM fin.txn t JOIN ref.branch b ON t.branch_cd = b.branch_cd\\nGROUP BY b.branch_name ORDER BY 1;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-04-001', 'TD-04', 'golden', 'Teradata integer-encoded dates (CYYMMDD) cast to DATE; naive TO_DATE reads epoch seconds', PARSE_JSON('{"description":"Teradata integer-encoded dates (CYYMMDD) cast to DATE; naive TO_DATE reads epoch seconds","dialect":"teradata","expected_rows":[[1,"2026-10-14"],[2,"1999-12-31"]],"fix_pattern":"FX-TD-04-A","fixed":{"snowflake":"SELECT posting_id,\\n       DATE_FROM_PARTS(1900 + CAST(FLOOR(posting_dt / 10000) AS INTEGER),\\n                       CAST(MOD(FLOOR(posting_dt / 100), 100) AS INTEGER),\\n                       CAST(MOD(posting_dt, 100) AS INTEGER)) AS posting_date\\nFROM gl_posting ORDER BY posting_id;\\n"},"fixture":"CREATE TABLE gl_posting (posting_id INTEGER, posting_dt INTEGER, amount DECIMAL(12,2));\\nINSERT INTO gl_posting VALUES (1, 1261014, 10.00), (2, 991231, 20.00);\\n","id":"TC-TD-04-001","issue_id":"TD-04","kind":"golden","naive":{"duckdb":"-- Snowflake TO_DATE on an integer string interprets it as seconds since the epoch\\nSELECT posting_id, CAST(to_timestamp(posting_dt) AS DATE) FROM gl_posting ORDER BY posting_id;\\n","expect":"diverge","snowflake":"SELECT posting_id, TO_DATE(TO_VARCHAR(posting_dt)) AS posting_date FROM gl_posting ORDER BY posting_id;"},"source_emulation":"-- Teradata internal date integer = (year - 1900) * 10000 + month * 100 + day\\nSELECT posting_id, make_date(1900 + posting_dt // 10000, (posting_dt // 100) % 100, posting_dt % 100)\\nFROM gl_posting ORDER BY posting_id;\\n","source_sql":"CREATE MULTISET TABLE fin.gl_posting (posting_id INTEGER, posting_dt INTEGER, amount DECIMAL(12,2));\\nSELECT posting_id, CAST(posting_dt AS DATE) AS posting_date FROM fin.gl_posting ORDER BY posting_id;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-05-001', 'TD-05', 'golden', 'Integer division truncates in Teradata and returns a decimal in Snowflake', PARSE_JSON('{"description":"Integer division truncates in Teradata and returns a decimal in Snowflake","dialect":"teradata","expected_rows":[[2]],"fix_pattern":"FX-TD-05-A","fixed":{"snowflake":"SELECT TRUNC(SUM(carton_count) / COUNT(*)) AS avg_cartons FROM shipments;"},"fixture":"CREATE TABLE shipments (shipment_id INTEGER, carton_count INTEGER);\\nINSERT INTO shipments VALUES (1, 3), (2, 2);\\n","id":"TC-TD-05-001","issue_id":"TD-05","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT SUM(carton_count) / COUNT(*) AS avg_cartons FROM shipments;"},"source_emulation":"-- INTEGER / INTEGER yields a truncated INTEGER in Teradata\\nSELECT SUM(carton_count) // COUNT(*) FROM shipments;\\n","source_sql":"CREATE MULTISET TABLE ops.shipments (shipment_id INTEGER, carton_count INTEGER);\\nSELECT SUM(carton_count) / COUNT(*) AS avg_cartons FROM ops.shipments;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-05-101', 'TD-05', 'detector', 'Decimal division and explicitly truncated division are not integer-division drift', PARSE_JSON('{"description":"Decimal division and explicitly truncated division are not integer-division drift","dialect":"teradata","expect_absent":["TD-05"],"expect_issues":[],"id":"TC-TD-05-101","issue_id":"TD-05","kind":"detector","source_sql":"CREATE MULTISET TABLE fin.t (amount DECIMAL(12,2), qty INTEGER);\\nSELECT amount / 2 FROM fin.t;\\nSELECT FLOOR(qty / 4) FROM fin.t;\\nSELECT CAST(qty AS DECIMAL(12,4)) / 3 FROM fin.t;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-06-101', 'TD-06', 'detector', 'BTEQ error handling dot-commands', PARSE_JSON('{"description":"BTEQ error handling dot-commands","dialect":"teradata","expect_issues":["TD-06"],"id":"TC-TD-06-101","issue_id":"TD-06","kind":"detector","source_sql":".LOGON tdprod/etl_user,$PASSWORD;\\nDELETE FROM stage.orders_batch;\\n.IF ERRORCODE <> 0 THEN .GOTO FAILED;\\nINSERT INTO sales.orders SELECT * FROM stage.orders_batch;\\n.IF ACTIVITYCOUNT = 0 THEN .QUIT 4;\\n.LABEL FAILED\\n.QUIT 8;\\n"}');
