INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-08-101', 'TD-08', 'profile', 'Update source is not unique on the join key', PARSE_JSON('{"description":"Update source is not unique on the join key","dialect":"teradata","expect_issues":["TD-08"],"id":"TC-TD-08-101","issue_id":"TD-08","kind":"profile","profile":{"update_sources":[{"distinct_keys":2,"key":["acct_id"],"row_count":3,"source":"fin.adjustment","statement":"upd_balance"}]},"source_sql":""}');
