INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-10-101', 'TD-10', 'detector', 'Identity columns', PARSE_JSON('{"description":"Identity columns","dialect":"teradata","expect_issues":["TD-10"],"id":"TC-TD-10-101","issue_id":"TD-10","kind":"detector","source_sql":"CREATE MULTISET TABLE dim.customer (\\n  customer_sk INTEGER GENERATED ALWAYS AS IDENTITY (START WITH 1 INCREMENT BY 1),\\n  customer_id VARCHAR(20)\\n);\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-11-001', 'TD-11', 'golden', 'Session time zone -04:00 assigns events to local business days; naive UTC cast shifts day boundaries', PARSE_JSON('{"description":"Session time zone -04:00 assigns events to local business days; naive UTC cast shifts day boundaries","dialect":"teradata","expected_rows":[["2026-09-30",1],["2026-10-01",2]],"fix_pattern":"FX-TD-11-A","fixed":{"snowflake":"SELECT CAST(CONVERT_TIMEZONE(''UTC'', ''America/New_York'', event_ts) AS DATE) AS event_date, COUNT(*)\\nFROM events GROUP BY 1 ORDER BY 1;\\n"},"fixture":"CREATE TABLE events (event_id INTEGER, event_ts TIMESTAMP);\\nINSERT INTO events VALUES (1, ''2026-10-01 02:30:00''), (2, ''2026-10-01 15:00:00''), (3, ''2026-10-02 03:59:00'');\\n","id":"TC-TD-11-001","issue_id":"TD-11","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT CAST(event_ts AS DATE) AS event_date, COUNT(*) FROM events GROUP BY 1 ORDER BY 1;"},"source_emulation":"-- extract holds UTC; the Teradata session evaluates CAST(... AS DATE) at UTC-04:00\\nSELECT CAST(event_ts - INTERVAL 4 HOUR AS DATE) AS d, COUNT(*) FROM events GROUP BY 1 ORDER BY 1;\\n","source_sql":"CREATE MULTISET TABLE web.events (event_id INTEGER, event_ts TIMESTAMP(6) WITH TIME ZONE);\\nSET TIME ZONE INTERVAL -''04:00'' HOUR TO MINUTE;\\nSELECT CAST(event_ts AS DATE) AS event_date, COUNT(*) FROM web.events GROUP BY 1 ORDER BY 1;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-TD-11-101', 'TD-11', 'profile', 'Non-UTC session time zone in the settings harvest', PARSE_JSON('{"description":"Non-UTC session time zone in the settings harvest","dialect":"teradata","expect_issues":["TD-11"],"id":"TC-TD-11-101","issue_id":"TD-11","kind":"profile","profile":{"settings":{"time_zone":"America Eastern"}},"source_sql":""}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-XD-07-001', 'XD-07', 'golden', 'MIN/MAX on strings follow the case-insensitive collation in SQL Server', PARSE_JSON('{"description":"MIN/MAX on strings follow the case-insensitive collation in SQL Server","dialect":"common","expected_rows":[["apple","Date"]],"fix_pattern":"FX-XD-07-A","fixed":{"snowflake":"SELECT MIN_BY(product_name, UPPER(product_name)), MAX_BY(product_name, UPPER(product_name)) FROM product;"},"fixture":"CREATE TABLE product (product_id INTEGER, product_name VARCHAR);\\nINSERT INTO product VALUES (1, ''apple''), (2, ''Banana''), (3, ''cherry''), (4, ''Date'');\\n","id":"TC-XD-07-001","issue_id":"XD-07","kind":"golden","naive":{"expect":"diverge","snowflake":"SELECT MIN(product_name), MAX(product_name) FROM product;"},"scan_dialect":"sqlserver","source_emulation":"SELECT arg_min(product_name, lower(product_name)), arg_max(product_name, lower(product_name)) FROM product;\\n","source_sql":"CREATE TABLE dbo.product (product_id INT, product_name VARCHAR(40));\\nSELECT MIN(product_name), MAX(product_name) FROM dbo.product;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-XD-08-001', 'XD-08', 'golden', 'T-SQL UPDATE ... FROM with a multi-match source; expected rows are the reconciled baseline', PARSE_JSON('{"description":"T-SQL UPDATE ... FROM with a multi-match source; expected rows are the reconciled baseline","dialect":"common","expected_rows":[[1,130],[2,205]],"fix_pattern":"FX-XD-08-A","fixed":{"snowflake":"UPDATE account SET balance = account.balance + j.amount\\nFROM (SELECT acct_id, SUM(amount) AS amount FROM adjustment GROUP BY acct_id) j\\nWHERE account.acct_id = j.acct_id;\\nSELECT acct_id, balance FROM account ORDER BY acct_id;\\n"},"fixture":"CREATE TABLE account (acct_id INTEGER, balance DECIMAL(12,2));\\nINSERT INTO account VALUES (1, 100.00), (2, 200.00);\\nCREATE TABLE adjustment (acct_id INTEGER, amount DECIMAL(12,2));\\nINSERT INTO adjustment VALUES (1, 10.00), (1, 20.00), (2, 5.00);\\n","id":"TC-XD-08-001","issue_id":"XD-08","kind":"golden","naive":{"expect":"diverge","snowflake":"UPDATE account SET balance = account.balance + j.amount FROM adjustment j WHERE account.acct_id = j.acct_id;\\nSELECT acct_id, balance FROM account ORDER BY acct_id;\\n"},"scan_dialect":"sqlserver","source_emulation":"SELECT a.acct_id, a.balance + coalesce(sum(j.amount), 0)\\nFROM account a LEFT JOIN adjustment j ON a.acct_id = j.acct_id\\nGROUP BY a.acct_id, a.balance ORDER BY a.acct_id;\\n","source_sql":"UPDATE a SET a.balance = a.balance + j.amount\\nFROM dbo.account a JOIN dbo.adjustment j ON a.acct_id = j.acct_id;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-XD-10-101', 'XD-10', 'detector', 'SUM over a FLOAT column', PARSE_JSON('{"description":"SUM over a FLOAT column","dialect":"common","expect_issues":["XD-10"],"id":"TC-XD-10-101","issue_id":"XD-10","kind":"detector","scan_dialect":"teradata","source_sql":"CREATE MULTISET TABLE sci.readings (sensor_id INTEGER, reading FLOAT);\\nSELECT sensor_id, SUM(reading) FROM sci.readings GROUP BY 1;\\n"}');
INSERT INTO KNOWLEDGE.TEST_CASE SELECT 'TC-XD-12-101', 'XD-12', 'detector', 'Explicit transactions with DDL in a procedure', PARSE_JSON('{"description":"Explicit transactions with DDL in a procedure","dialect":"common","expect_issues":["XD-12"],"id":"TC-XD-12-101","issue_id":"XD-12","kind":"detector","scan_dialect":"sqlserver","source_sql":"CREATE PROCEDURE dbo.rebuild AS\\nBEGIN\\n  BEGIN TRANSACTION;\\n  TRUNCATE TABLE dbo.stage;\\n  INSERT INTO dbo.stage SELECT * FROM dbo.src;\\n  COMMIT TRANSACTION;\\nEND\\n"}');
